// Synthesised locally, opt-in only. No audio files or network requests.
export function createSoundscape({host=globalThis,getRestored=()=>0,isHidden=()=>false,schedule=setTimeout,cancel=clearTimeout}={}){
 let context=null,master=null,enabled=false,timer=null;const loops=[];
 function stopBirds(){if(timer!==null)cancel(timer);timer=null;}
 function chirp(){if(!enabled||!context||context.state!=='running'||isHidden())return;const n=Math.max(0,Math.min(6,getRestored()));if(n){const t=context.currentTime,o=context.createOscillator(),g=context.createGain();o.type='sine';o.frequency.setValueAtTime(1900+Math.random()*1000,t);o.frequency.exponentialRampToValueAtTime(1350+Math.random()*650,t+.18);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.014,t+.025);g.gain.exponentialRampToValueAtTime(.0001,t+.24);o.connect(g);g.connect(master);o.start(t);o.stop(t+.26);o.onended=()=>{o.disconnect();g.disconnect();};}timer=schedule(chirp,Math.max(1200,6800-n*800)+Math.random()*1200);}
 function init(){const Audio=host.AudioContext||host.webkitAudioContext;if(!Audio)throw Error('Web Audio unavailable');context=new Audio();master=context.createGain();master.gain.value=.55;master.connect(context.destination);const noise=context.createBuffer(1,context.sampleRate*2,context.sampleRate),data=noise.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;
 for(const [frequency,volume] of [[430,.035],[1100,.022]]){const source=context.createBufferSource(),filter=context.createBiquadFilter(),gain=context.createGain();source.buffer=noise;source.loop=true;filter.type='lowpass';filter.frequency.value=frequency;gain.gain.value=volume;source.connect(filter);filter.connect(gain);gain.connect(master);source.start();loops.push(source);const lfo=context.createOscillator(),depth=context.createGain();lfo.frequency.value=frequency===430?.07:.14;depth.gain.value=volume*.5;lfo.connect(depth);depth.connect(gain.gain);lfo.start();loops.push(lfo);}}
 async function setEnabled(value){stopBirds();enabled=false;if(!value){try{await context?.suspend();}catch{}return false;}try{if(!context)init();await context.resume();if(context.state!=='running')return false;enabled=true;chirp();return true;}catch{await dispose();return false;}}
 async function visibility(){stopBirds();if(!context||!enabled)return;try{if(isHidden())await context.suspend();else{await context.resume();chirp();}}catch{enabled=false;}}
 async function dispose(){stopBirds();enabled=false;for(const source of loops.splice(0))try{source.stop();source.disconnect();}catch{}try{await context?.close();}catch{}context=null;master=null;}
 return {setEnabled,visibility,dispose,get context(){return context;},get enabled(){return enabled;}};
}
